export const COUNTRIES_MAP = new Map<string, Country>(
  COUNTRIES.map((c) => [c.code.toUpperCase(), c])
)

export const CURRENCIES_MAP = new Map<string, Currency>(
  CURRENCIES.map((c) => [c.code.toUpperCase(), c])
)

export function getFlagEmoji(countryCode: string): string {
  if (!countryCode) return ""
  const codePoints = countryCode
    .toUpperCase()
    .split("")
    .map((c) => 127397 + c.charCodeAt(0))
  return String.fromCodePoint(...codePoints)
}

export function getPrimaryTimezoneForCountry(countryCode?: string | null): string | undefined {
  if (!countryCode) return undefined
  const code = countryCode.toUpperCase().trim()
  return PRIMARY_TIMEZONES[code]
}

export function getCountryByCode(countryCode?: string | null): Country | undefined {
  if (!countryCode) return undefined
  return COUNTRIES_MAP.get(countryCode.toUpperCase().trim())
}

export function getCurrencyByCode(currencyCode?: string | null): Currency | undefined {
  if (!currencyCode) return undefined
  return CURRENCIES_MAP.get(currencyCode.toUpperCase().trim())
}

export function formatCountryLabel(countryCode?: string | null): string {
  if (!countryCode) return ""
  const c = getCountryByCode(countryCode)
  if (c) {
    return `${c.flag} ${c.name} (${c.code})`
  }
  return `${getFlagEmoji(countryCode)} ${countryCode}`
}

export function formatCurrencyLabel(currencyCode?: string | null): string {
  if (!currencyCode) return ""
  const c = getCurrencyByCode(currencyCode)
  if (c) {
    return `${c.code} - ${c.name} (${c.symbol})`
  }
  return currencyCode
}

export function getTimezoneOffset(tz: string): string {
  try {
    const formatter = new Intl.DateTimeFormat("en-US", {
      timeZone: tz,
      timeZoneName: "shortOffset",
    })
    const parts = formatter.formatToParts(new Date())
    const offsetPart = parts.find((p) => p.type === "timeZoneName")
    return offsetPart?.value ?? ""
  } catch {
    return ""
  }
}

export function formatTimezoneLabel(tz?: string | null): string {
  if (!tz) return ""
  const offset = getTimezoneOffset(tz)
  return offset ? `${tz} (${offset})` : tz
}

// Generate IANA timezones list
export function getStandardTimezones(): TimezoneOption[] {
  let tzList: string[] = []
  if (typeof Intl !== "undefined" && typeof Intl.supportedValuesOf === "function") {
    tzList = Intl.supportedValuesOf("timeZone")
  }
  if (!tzList.includes("UTC")) {
    tzList = ["UTC", ...tzList]
  }

  return tzList.map((tz) => {
    const offset = getTimezoneOffset(tz)
    return {
      tz,
      offset,
      label: offset ? `${tz} (${offset})` : tz,
    }
  })
}
